CREATE FUNCTION pg_temp.alert38644_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL alert38644: %',label; END IF;
 RAISE NOTICE 'PASS alert38644: %',label;
END$$;
CREATE TEMP VIEW alert38644_raw AS
 SELECT x.* FROM alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'rake_records') AS x(
 id uuid,hand_id uuid,table_id uuid,club_id uuid,rake_amount numeric,created_at timestamptz,
 is_tournament boolean,tournament_id uuid,source text,metadata jsonb,rake_method text);
CREATE TEMP VIEW alert38644_attributions AS
 SELECT x.* FROM alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'beneficiary_attributions') AS x(
 id uuid,hand_id uuid,rake_record_id uuid,table_id uuid,club_id uuid,player_id uuid,created_at timestamptz,
 rake_amount numeric,weighted_rake_credit numeric,rake_method text);
SELECT pg_temp.alert38644_assert(count(*)=59 AND count(DISTINCT id)=59 AND count(DISTINCT hand_id)=59
 AND sum(rake_amount)=160,'all 59 original source identities and 160 table rake retained') FROM alert38644_raw;
SELECT pg_temp.alert38644_assert(count(*)=59 AND count(DISTINCT a.id)=59 AND sum(a.weighted_rake_credit)=79.89
 AND bool_and(a.hand_id=r.hand_id AND a.table_id=r.table_id
  AND a.club_id='a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid
  AND r.club_id='2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid
  AND a.player_id='c402b38e-7ba6-40bf-a2d3-d65376d28ccf'::uuid),
 '59 exact attributions preserve SHARK 79.89 independently of DSS host')
 FROM alert38644_attributions a JOIN alert38644_raw r ON r.id=a.rake_record_id;
SELECT pg_temp.alert38644_assert(bool_and(r.created_at>=s.joined_at AND r.created_at<s.left_at
 AND r.table_id=s.table_id AND a.club_id=s.club_id AND a.player_id=s.user_id),
 'every source falls within the captured SHARK seat session')
 FROM alert38644_raw r JOIN alert38644_attributions a ON a.rake_record_id=r.id
 CROSS JOIN alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'seat_session') AS s(
 table_id uuid,club_id uuid,user_id uuid,joined_at timestamptz,left_at timestamptz);
SELECT pg_temp.alert38644_assert(NOT EXISTS(SELECT 1 FROM public.rake_records r JOIN alert38644_raw e USING(id))
 AND NOT EXISTS(SELECT 1 FROM public.rakeback_periods WHERE id='a8e2fed5-e15e-4622-aff6-3177c0b9a1c7'),
 'fixture requires absent original IDs; never overwrite an existing record');
SELECT pg_temp.alert38644_assert((SELECT starts_at>'2026-09-14 07:00:00Z'::timestamptz
 FROM public.accounting_cash_accrual_cutover WHERE singleton),'real candidate cutover follows the disputed historical week');

-- Opening projection only. Original bank evidence stays in the temp evidence
-- relation: it lacks some mandatory full-ledger columns and is not promoted
-- into new v2 bank authority. No historical contract, second contributor,
-- current membership or historical seat-admission authority is invented.
-- Noncaptured default columns are schema defaults, not claimed original data.
SET LOCAL session_replication_role=replica;
