 ('a41434bb-8d0c-400a-8f0d-e8b3d65afed4','SHARK CLUB',false,'fade0000-0000-0000-0000-000000000001');
INSERT INTO auth.users(id) VALUES('c402b38e-7ba6-40bf-a2d3-d65376d28ccf');
INSERT INTO public.rake_records(id,hand_id,table_id,club_id,rake_amount,created_at,is_tournament,tournament_id,source,metadata,rake_method)
 SELECT id,hand_id,table_id,club_id,rake_amount,created_at,is_tournament,tournament_id,source,metadata,rake_method FROM alert38644_raw;
INSERT INTO public.rake_attributions(id,hand_id,rake_record_id,table_id,club_id,player_id,created_at,rake_amount,weighted_rake_credit,rake_method)
 SELECT id,hand_id,rake_record_id,table_id,club_id,player_id,created_at,rake_amount,weighted_rake_credit,rake_method FROM alert38644_attributions;
INSERT INTO public.rakeback_periods(id,user_id,club_id,period_start,period_end,rake_generated,rakeback_rate,rakeback_amount,status,
 paid_at,created_at,rakeback_earned,total_rake_paid,deferred_reason,deferred_at,defer_count)
 SELECT p.* FROM alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'pending_period') AS p(
 id uuid,user_id uuid,club_id uuid,period_start date,period_end date,rake_generated numeric,rakeback_rate numeric,rakeback_amount numeric,
 status text,paid_at timestamptz,created_at timestamptz,rakeback_earned numeric,total_rake_paid numeric,
 deferred_reason text,deferred_at timestamptz,defer_count integer);
INSERT INTO public.agent_commissions(id,club_id,user_id,amount,commission_rate,source_type,source_id,created_at,settled_at)
 SELECT c.* FROM alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'bank_admission'->'same_source_agent_commissions') AS c(
 id uuid,club_id uuid,user_id uuid,amount numeric,commission_rate numeric,source_type text,source_id uuid,created_at timestamptz,settled_at timestamptz);
SET LOCAL session_replication_role=origin;
SET LOCAL request.jwt.claims='{"role":"service_role"}';
CREATE TEMP VIEW alert38644_current_originals AS
 SELECT 'raw' AS kind,r.id,to_jsonb(r) AS document FROM public.rake_records r JOIN alert38644_raw e USING(id)
 UNION ALL SELECT 'attribution',a.id,to_jsonb(a) FROM public.rake_attributions a JOIN alert38644_attributions e USING(id)
 UNION ALL SELECT 'commission',c.id,to_jsonb(c) FROM public.agent_commissions c JOIN alert38644_raw r ON r.hand_id=c.source_id
 UNION ALL SELECT 'period',p.id,to_jsonb(p) FROM public.rakeback_periods p WHERE p.id='a8e2fed5-e15e-4622-aff6-3177c0b9a1c7';
CREATE TEMP TABLE alert38644_originals AS SELECT * FROM alert38644_current_originals;
CREATE TEMP TABLE alert38644_preview AS
 SELECT club_id,public.fn_cash_rakeback_period_basis(club_id,'2026-09-07','2026-09-13',ARRAY['c402b38e-7ba6-40bf-a2d3-d65376d28ccf'::uuid]) AS result
 FROM (VALUES('2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid),('a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid)) AS c(club_id);
SELECT pg_temp.alert38644_assert((result->>'total_rake')::numeric=0 AND result->>'legacy_pending_conflicts'='1'
 AND result->>'payable'='false' AND result->>'written'='0','DSS preview retains its conflict without appropriating SHARK earnings')
 FROM alert38644_preview WHERE club_id='2a1132b9-5ba2-42e6-9f01-30a7fcffebe3';
SELECT pg_temp.alert38644_assert((result->>'total_rake')::numeric=79.89 AND result->'rows'->0->>'source_count'='59'
 AND result->>'missing_terms_count'='59' AND result->>'status'='needs_reconciliation'
 AND result->>'payable'='false' AND result->>'written'='0',
 'SHARK preview preserves exact volume while missing historical contracts prevent payable certification')
 FROM alert38644_preview WHERE club_id='a41434bb-8d0c-400a-8f0d-e8b3d65afed4';
CREATE TEMP TABLE alert38644_outcomes AS
 SELECT r.id,public.fn_process_cash_accounting_source(r.id) AS result FROM alert38644_raw r ORDER BY r.created_at,r.id;
SELECT pg_temp.alert38644_assert(count(*)=59 AND bool_and((result->>'status'='blocked'
 AND result->>'reason'='cash_source_legacy_unverified' AND result->>'recorded'='true'
 AND result->'credits'='[]'::jsonb AND result->'scope'->>'kind'='unknown') IS TRUE),
 'all 59 legacy sources retain durable explicit refusal with no guessed coordinator or credited share') FROM alert38644_outcomes;
SELECT pg_temp.alert38644_assert(count(*)=59 AND bool_and(b.status='legacy_unverified' AND b.plan IS NULL),
 'legacy batch receipts cannot claim historical contracts or accrual')
 FROM public.accounting_cash_accrual_batches b JOIN alert38644_raw r ON r.id=b.rake_record_id;

SELECT pg_temp.alert38644_assert(count(*)=59 AND count(DISTINCT a.id)=59 AND count(DISTINCT o.id)=59
 AND bool_and((a.attempt=1 AND w.attempts=1 AND a.status='blocked' AND w.status='blocked'
  AND a.reason='cash_source_legacy_unverified' AND a.earned_at=raw.created_at
  AND o.result->>'rake_record_id'=raw.id::text AND o.result->>'hand_id'=raw.hand_id::text
  AND a.source_fingerprint=o.result->>'source_fingerprint' AND w.source_fingerprint=a.source_fingerprint
  AND a.scope=o.result->'scope' AND a.result=o.result) IS TRUE),
 'all 59 first refusals bind exact original sources to persisted attempt receipts and latest work pointers')
 FROM alert38644_outcomes o JOIN alert38644_raw raw ON raw.id=o.id
 JOIN public.accounting_cash_source_receipts a ON a.id::text=o.result->>'receipt_id' AND a.rake_record_id=o.id
 JOIN public.accounting_cash_source_work w ON w.rake_record_id=o.id AND w.receipt_id=a.id;
CREATE TEMP VIEW alert38644_current_first_receipts AS
 SELECT a.id,to_jsonb(a)::text AS document FROM public.accounting_cash_source_receipts a
 JOIN alert38644_raw r ON r.id=a.rake_record_id WHERE a.attempt=1;
CREATE TEMP TABLE alert38644_first_receipt_snapshot AS SELECT * FROM alert38644_current_first_receipts;
CREATE TEMP TABLE alert38644_requests AS
 SELECT club_id,public.fn_rakeback_recompute_periods(club_id,'2026-09-07','2026-09-13',NULL) AS result
 FROM (VALUES('2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid),('a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid)) AS c(club_id);
SELECT pg_temp.alert38644_assert(count(*)=2 AND bool_and((result->>'status'='blocked'
 AND result->>'reason'='historical_week_before_observed_source_cutover' AND result->>'written'='0'
 AND result->>'request_state'='blocked' AND result->>'request_recorded'='true') IS TRUE),
 'both club books use one certified replacement and remain durably blocked') FROM alert38644_requests;
SELECT pg_temp.alert38644_assert(count(*)=2 AND bool_and((q.status='blocked' AND q.last_result->>'written'='0') IS TRUE),
 'reported period refusals resolve to exact durable request IDs')
 FROM alert38644_requests r JOIN public.accounting_period_recompute_requests q
 ON q.id=(r.result->>'request_id')::uuid AND q.club_id=r.club_id
 AND q.period_start='2026-09-07' AND q.period_end='2026-09-13';
CREATE TEMP TABLE alert38644_retries AS
 SELECT r.id,public.fn_process_cash_accounting_source(r.id) AS result FROM alert38644_raw r ORDER BY r.created_at,r.id;
SELECT pg_temp.alert38644_assert(count(*)=59 AND bool_and((result->>'status'='blocked'
 AND result->>'reason'='cash_source_legacy_unverified' AND result->>'attempt'='2'
 AND result->'credits'='[]'::jsonb AND result->'scope'->>'kind'='unknown') IS TRUE),
 'retry retains the historical refusal and unknown scope instead of inventing a current contract') FROM alert38644_retries;

SELECT pg_temp.alert38644_assert(count(*)=59 AND count(DISTINCT a.id)=59 AND count(DISTINCT r.id)=59
 AND bool_and((a.attempt=2 AND w.attempts=2 AND a.status='blocked' AND w.status='blocked'
  AND a.reason='cash_source_legacy_unverified' AND a.earned_at=raw.created_at
  AND r.result->>'rake_record_id'=raw.id::text AND r.result->>'hand_id'=raw.hand_id::text
  AND a.source_fingerprint=r.result->>'source_fingerprint' AND w.source_fingerprint=a.source_fingerprint
  AND a.source_fingerprint=o.result->>'source_fingerprint'
  AND a.id::text IS DISTINCT FROM o.result->>'receipt_id'
  AND r.result->'scope'=o.result->'scope'
  AND a.scope=r.result->'scope' AND a.result=r.result) IS TRUE),
 'all 59 second refusals persist new immutable attempts and advance only their exact latest work pointers')
 FROM alert38644_retries r JOIN alert38644_outcomes o ON o.id=r.id JOIN alert38644_raw raw ON raw.id=r.id
 JOIN public.accounting_cash_source_receipts a ON a.id::text=r.result->>'receipt_id' AND a.rake_record_id=r.id
 JOIN public.accounting_cash_source_work w ON w.rake_record_id=r.id AND w.receipt_id=a.id;
SELECT pg_temp.alert38644_assert(count(*)=118 AND count(*) FILTER(WHERE a.attempt=1)=59
 AND count(*) FILTER(WHERE a.attempt=2)=59 AND count(DISTINCT a.rake_record_id)=59,
 'both exact59-attempt histories survive without fabricated acknowledgement or extra source attempts')
 FROM public.accounting_cash_source_receipts a JOIN alert38644_raw r ON r.id=a.rake_record_id;
SELECT pg_temp.alert38644_assert((SELECT count(*) FROM alert38644_first_receipt_snapshot)=59
 AND NOT EXISTS((SELECT * FROM alert38644_first_receipt_snapshot EXCEPT SELECT * FROM alert38644_current_first_receipts)
 UNION ALL(SELECT * FROM alert38644_current_first_receipts EXCEPT SELECT * FROM alert38644_first_receipt_snapshot)),
 'retry preserves every field of all59 first-attempt receipts byte-equivalent as canonical JSON text');
SELECT pg_temp.alert38644_assert(NOT EXISTS(SELECT 1 FROM public.accounting_cash_rake_sources s JOIN alert38644_raw r ON r.id=s.rake_record_id)
 AND NOT EXISTS(SELECT 1 FROM public.accounting_cash_bank_receipts b JOIN alert38644_raw r ON r.id=b.rake_record_id)
 AND NOT EXISTS(SELECT 1 FROM public.rakeback_stats_applied s JOIN alert38644_raw r ON r.id=s.rake_record_id),
 'no source liability, bank evidence or player stats is fabricated for the 59 unknown historical sources');
SELECT pg_temp.alert38644_assert(NOT EXISTS(SELECT 1 FROM public.accounting_rakeback_period_calculations WHERE period_id='a8e2fed5-e15e-4622-aff6-3177c0b9a1c7')
 AND NOT EXISTS(SELECT 1 FROM public.rakeback_period_payouts WHERE rakeback_period_id='a8e2fed5-e15e-4622-aff6-3177c0b9a1c7')
 AND NOT EXISTS(SELECT 1 FROM public.rakeback_periods WHERE user_id='c402b38e-7ba6-40bf-a2d3-d65376d28ccf'
  AND club_id='a41434bb-8d0c-400a-8f0d-e8b3d65afed4' AND period_start='2026-09-07'),
 'DSS remains unpaid and uncertified; no replacement SHARK payable is silently created');
SELECT pg_temp.alert38644_assert(NOT has_function_privilege('service_role','public.fn_close_settlement_period(uuid)','EXECUTE'),
 'legacy direct close cannot bypass the one certified weekly authority');
SELECT pg_temp.alert38644_assert(NOT EXISTS((SELECT * FROM alert38644_originals EXCEPT SELECT * FROM alert38644_current_originals)
 UNION ALL(SELECT * FROM alert38644_current_originals EXCEPT SELECT * FROM alert38644_originals)),
 'all captured raw records, attributions, 118 legacy commissions and the disputed 3.99 period remain byte-equivalent as JSON');
SELECT pg_temp.alert38644_assert(count(*)=118 AND count(DISTINCT c.user_id)=4 AND sum(c.amount)=54.17
 AND bool_and(c.club_id='2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid AND c.settled_at IS NULL),
 '118 original unsettled DSS commissions totaling54.17 survive unchanged')
 FROM public.agent_commissions c JOIN alert38644_raw r ON r.hand_id=c.source_id;
SELECT pg_temp.alert38644_assert(count(*)=59 AND count(DISTINCT b.ledger_id)=59 AND sum(b.amount)=160
 AND bool_and(b.amount=r.rake_amount AND b.hand_id=r.hand_id AND b.created_at=r.created_at
  AND b.table_id=r.table_id AND b.club_id=r.club_id AND b.to_entity_id=r.club_id
  AND b.to_type='club_treasury' AND b.category='rake' AND b.status='posted'),
 'original posted DSS bank receipts remain linked to all 59 hands and160.00')
 FROM alert38644_evidence e CROSS JOIN LATERAL jsonb_to_recordset(e.document->'bank_admission'->'rake_bank_ledger') AS b(
 rake_record_id uuid,ledger_id uuid,hand_id uuid,amount numeric,created_at timestamptz,table_id uuid,club_id uuid,to_entity_id uuid,to_type text,category text,status text)
 JOIN alert38644_raw r ON r.id=b.rake_record_id;
SELECT pg_temp.alert38644_assert((document->'bank_admission'->'admission_ledger'->0->>'amount')::numeric=900
 AND document->'bank_admission'->'admission_ledger'->0->>'club_id'='a41434bb-8d0c-400a-8f0d-e8b3d65afed4'
 AND (document->'bank_admission'->'cashout_ledger'->0->>'amount')::numeric=1383.15
 AND document->'bank_admission'->'cashout_ledger'->0->>'club_id'='a41434bb-8d0c-400a-8f0d-e8b3d65afed4',
 'recorded SHARK900.00 funding and1383.15 return are retained without relabeling admission') FROM alert38644_evidence;
-- Same exact evidence and rollback scope; public coordinator retry dependency.
\ir coordinator-retry.sql
ROLLBACK;
